const body = $input.first().json.body;
const topic = body.topic || '';
const mode = body.mode || 'assisted';
const audit = body.audit !== false;

if (!topic) {
  throw new Error('Missing required field: topic');
}

return [{ json: { topic, mode, audit, timestamp: new Date().toISOString() } }];

// Prepare the dispatch request body as a proper object
const topic = $json.topic;
const mode = $json.mode;

const requestBody = {
  task: `Design a deep research execution prompt for: ${topic}. Mode: ${mode}. Produce a self-contained prompt that an external research tool can execute.`,
  context: {
    agent_id: 'prompter',
    prompt: `You are a Deep Research Architect. Design a comprehensive research execution prompt for the topic: ${topic}. Include: research questions, search strategy, expected sources, quality criteria. Mode: ${mode}.`,
    level: 3,
    domain: 'research'
  }
};

return [{ json: requestBody }];

const result = $input.first().json;
const agentResult = result.result || result;
const improvedPrompt = agentResult.improved_prompt || agentResult.prompt || '';

return [{
  json: {
    topic: $('Validate Input').first().json.topic,
    execution_prompt: improvedPrompt,
    changes: agentResult.changes_made || [],
    level: agentResult.level_applied || 0
  }
}];

// Prepare RAG query body
const executionPrompt = $json.execution_prompt;

return [{
  json: {
    query: executionPrompt,
    top_k: 10
  }
}];

const retrieval = $input.first().json;
const context = retrieval.context || {};
const chunks = context.retrieved_chunks || [];

const researchContext = chunks.map(c => {
  const content = c.chunk?.content || '';
  const score = c.score || 0;
  const title = c.chunk?.metadata?.title || 'unknown';
  return `[${title}] (score: ${score.toFixed(3)}) ${content.substring(0, 200)}`;
}).join('\n---\n');

return [{
  json: {
    topic: $('Extract Execution Prompt').first().json.topic,
    execution_prompt: $('Extract Execution Prompt').first().json.execution_prompt,
    research_context: researchContext,
    chunks_found: chunks.length
  }
}];

// Prepare audit dispatch body
const topic = $('Validate Input').first().json.topic;
const chunksFound = $json.chunks_found;

return [{
  json: {
    task: `Audit the research output for topic: ${topic}. Evaluate across 10 dimensions: source integrity, perspective diversity, evidence quality, bias detection, confidence calibration, information gaps, internal consistency, relevance, structure, actionability.`,
    context: {
      agent_id: 'critic-premortem',
      plan: `Research on ${topic}. Retrieved ${chunksFound} knowledge chunks.`,
      level: 2
    }
  }
}];

const audit = $input.first().json;
const auditResult = audit.result || audit;

return [{
  json: {
    topic: $('Validate Input').first().json.topic,
    execution_prompt: $('Extract Execution Prompt').first().json.execution_prompt,
    research_context: $('Build Research Context').first().json.research_context,
    audit_summary: auditResult.summary || 'No audit summary',
    failure_reasons: auditResult.failure_reasons || [],
    checklist: auditResult.checklist || []
  }
}];

const data = $input.first().json;

const output = {
  status: 'completed',
  topic: data.topic,
  execution_prompt: data.execution_prompt,
  research_context: data.research_context || '',
  audit: {
    summary: data.audit_summary || 'Audit skipped',
    failure_reasons: data.failure_reasons || [],
    checklist: data.checklist || []
  },
  timestamp: new Date().toISOString()
};

return [{ json: output }];
